export function useUser() {
  return useSearchParam('user', asString);
}

export function useSheetId() {
  return useSearchParam('sheet', asString);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson, putJson } from '../../api/http';
import { claimsKey } from '../claims/useClaims';
import { peopleKey } from '../people/people.slot';
import { periodsKey } from '../periods/periods.slot';
import { useSheetId } from '../session/useSession';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';

// Choose a sheet by typing its id and loading it. Loading drops everything cached for that sheet,
// so the screen re-reads it from the store (an id never used before starts empty). Its people, claims
// and periods are read before it becomes the active sheet, so its rows show as soon as its id does.
export function SheetPicker() {
  const [sheetId, setSheetId] = useSheetId();
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const load = useMutation({
    mutationFn: async (id: string) => {
      if (id.trim() === '') throw new Error('Enter a sheet id');
      return putJson<{ id: string }>(`/api/sheets/${encodeURIComponent(id.trim())}`);
    },
    onSuccess: async (sheet) => {
      queryClient.removeQueries({ queryKey: ['sheet', sheet.id] });
      const base = `/api/sheets/${encodeURIComponent(sheet.id)}`;
      await Promise.all([
        queryClient.fetchQuery({ queryKey: peopleKey(sheet.id), queryFn: () => getJson(`${base}/people`) }),
        queryClient.fetchQuery({ queryKey: claimsKey(sheet.id), queryFn: () => getJson(`${base}/claims`) }),
        queryClient.fetchQuery({ queryKey: periodsKey(sheet.id), queryFn: () => getJson(`${base}/periods`) }),
      ]).catch(() => {
        // the panels show their own read errors
      });
      setSheetId(sheet.id);
    },
  });

  const submit = useSubmitOnce(load);
  return (
    <div data-testid="sheet-bar">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submit(input);
        }}
      >
        <label>
          Sheet{' '}
          <input
            data-testid="sheet-id-input"
            value={input}
            onChange={(e) => {
              setInput(e.target.value);
              load.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
          Load
        </button>
      </form>
      <p>
        Active sheet: <strong data-testid="sheet-current-id">{sheetId}</strong>
      </p>
      {load.isError && (
        <p data-testid="sheet-load-error" role="alert">
          {load.error.message}
        </p>
      )}
    </div>
  );
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;

