 * `<td>` per person in the cells slot, at the same order, so the columns line up.
 */
export const PersonHeads = defineSlot<{ sheetId: string; user: string }>('person.heads');
export const PersonCells = defineSlot<{ sheetId: string; user: string; personId: number }>('person.cells');
import { defineSlot } from '../Slot';

/**
 * The body of the screen once a user is signed in and a sheet is loaded. Every per-sheet feature
 * fills it; its context is the active sheet id and the signed-in user.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
import { useUser } from '../session/useSession';

type SheetToday = { id: string; today: string; archived: boolean };

/** The key every feature reads the sheet's today under: date decisions and default dates use it, never the real clock. */
export const sheetTodayKey = (sheetId: string) => ['sheet', sheetId, 'today'] as const;

export function useSheetToday(sheetId: string) {
  return useQuery({
    queryKey: sheetTodayKey(sheetId),
    queryFn: () => getJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`),
  });
}

// The sheet's today: shown, and changeable. Changing it re-reads the whole sheet, since anything
// that depends on the date may now show differently. Also whether the sheet is archived, and the
// button a steward archives it with; the two share the sheet's error.
function SheetTodayPanel({ sheetId }: { sheetId: string; user: string }) {
  const today = useSheetToday(sheetId);
  const [input, setInput] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: async (date: string) => {
      if (date.trim() === '') throw new Error('Enter a date');
      return putJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today: date.trim(), by: user ?? '' });
    },
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetTodayKey(sheetId), saved);
      await queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'today',
      });
    },
  });

  const archive = useMutation({
    mutationFn: () => postJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, { by: user ?? '' }),
    onSuccess: (saved) => queryClient.setQueryData(sheetTodayKey(sheetId), saved),
  });

  const submit = useSubmitOnce(save);
  const submitArchive = useSubmitOnce(archive);
  return (
    <section data-testid="sheet-today-panel">
      <p>
        Today: <strong data-testid="sheet-today">{today.data?.today ?? ''}</strong>
      </p>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          archive.reset();
          submit(input);
        }}
      >
        <input
          type="date"
          data-testid="sheet-today-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            save.reset();
            archive.reset();
          }}
        />{' '}
        <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
          Set today
        </button>
      </form>
      <p>
        Archived:{' '}
        <strong data-testid="sheet-archived">{today.data === undefined ? '' : today.data.archived ? 'yes' : 'no'}</strong>{' '}
        <button
          type="button"
          data-testid="sheet-archive"
          disabled={archive.isPending}
          onClick={() => {
            save.reset();
            submitArchive(undefined);
          }}
        >
          Archive sheet
        </button>
      </p>
      {(save.isError || archive.isError || today.isError) && (
        <p data-testid="sheet-error" role="alert">
          {(save.error ?? archive.error ?? today.error)?.message}
        </p>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 0, Component: SheetTodayPanel });
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/useClaims';
import { useOverdue } from '../overdue/overdue.slot';
import { usePeople } from '../people/people.slot';
import { useSheetDueTotal } from '../rates/rates.slot';
import { showHundredths } from '../rates/useRates';
import { STATUSES } from '../summary/summary.slot';

// The header's counters, at the top of the sheet: the people on it (retired people included), the claims in each
// status (as the summary counts them), and the sheet's due-total and overdue-total (as the rollups show them).
function SheetHeader({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const due = useSheetDueTotal(sheetId);
  const overdue = useOverdue(sheetId).sheet;
  return (
    <header data-testid="sheet-header">
      <p>
        People: <strong data-testid="header-people-count">{(people.data ?? []).length}</strong>{' '}
        {STATUSES.map((s) => (
          <span key={s}>
            {s}: <strong data-testid={`header-claims-${s}-count`}>{(claims.data ?? []).filter((c) => c.status === s).length}</strong>{' '}
          </span>
        ))}
        Due total: <strong data-testid="header-due-total">{showHundredths(due)}</strong>{' '}
        Overdue total: <strong data-testid="header-overdue-total">{showHundredths(overdue.cents)}</strong>
      </p>
    </header>
  );
}

export const contribution = SheetBody.fill({ order: -10, Component: SheetHeader });
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
