-- Closing a period also fixes each person's due-total for it, for every person on the sheet at that moment
-- (a person added later has none: 0.00). The period's closed_total is the sum of these. Reopening removes them.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The users watching each person, in the order they started watching (id order). A user watches a person at most once.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
-- A claim's editor lock: the signed-in user whose open editor holds the claim. Others cannot open its
-- editor or save it until the holder saves or cancels, or the sheet's today changes (every lock is dropped).
CREATE TABLE claim_lock (
    claim_id  BIGINT       PRIMARY KEY REFERENCES claim (id),
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    locked_by VARCHAR(200) NOT NULL
);
CREATE INDEX claim_lock_sheet ON claim_lock (sheet_id);
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheets: a row per id ever loaded. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Create the sheet if its id was never used (its today the real date); an existing sheet is left as it is. */
    public void ensure(String id) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, COALESCE((SELECT today FROM sheet WHERE id = ?), ?)",
                id, id, LocalDate.now());
    }

    /**
     * The sheet's today. Every decision that depends on the date, and every default date, uses
     * this — never the real clock. A sheet not yet stored is on the real date.
     */
    public LocalDate today(String id) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : LocalDate.now(), id);
    }

    public void setToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", today, id);
    }

    /** Whether the sheet is archived: then every change to it is refused. A sheet not yet stored is not. */
    public boolean isArchived(String id) {
        return jdbc.query("SELECT archived FROM sheet WHERE id = ?", rs -> rs.next() && rs.getBoolean(1), id);
    }

    /** Refuse a change to the sheet while it is archived. */
    public void refuseArchived(String id) throws BadRequestException {
        if (isArchived(id)) {
            throw new BadRequestException("This sheet is archived");
        }
    }

    public void archive(String id) {
        jdbc.update("UPDATE sheet SET archived = TRUE WHERE id = ?", id);
    }
}
package net.officefloor.hq.app.sheet;

public record SheetResponse(String id) {
}
package net.officefloor.hq.app.access;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses any change by a viewer on the sheet, or to an archived sheet, before it touches the store. */
public class RefuseViewer {
    public void refuse(@Val SheetResponse sheet, @Val ChangedBy by, RoleRepository roles,
            SheetRepository sheets) throws BadRequestException {
        if (roles.isViewer(sheet.id(), by.name())) {
            throw new BadRequestException("A viewer may not change anything on this sheet");
        }
        sheets.refuseArchived(sheet.id());
    }
}
