import { useUser } from './useSession';

// Who is signed in, and a way to sign out.
export function UserBar() {
  const [user, setUser] = useUser();
  return (
    <div data-testid="user-bar">
      Signed in as <strong data-testid="current-user">{user}</strong>{' '}
      <button type="button" data-testid="signout" onClick={() => setUser(undefined)}>
        Sign out
      </button>
    </div>
  );
}
import { Link } from '@tanstack/react-router';
import { AppNav } from '../../slots/defs/appNav';

// WORKED EXAMPLE of the one mechanism every shared region uses. This file is the whole of Home's
// presence in the nav bar; the shell was not touched to put it there. A new page adds its own file
// exactly like this one.
export const contribution = AppNav.fill({
  order: 0,
  Component: () => (
    <Link to="/" data-testid="nav-home">
      Home
    </Link>
  ),
});
import { ClaimCells } from '../../slots/defs/claimRow';

// A claim's status log: one line per status it has had, oldest first, as `<STATUS> by <user> on <date> due=<due>`
// (the sheet's today when it changed, and its due as computed then).
function ClaimLog({ claim }: { sheetId: string; user: string; personId: number; claim: { log?: string[] } }) {
  return (
    <ol data-testid="claim-log">
      {(claim.log ?? []).map((line, i) => (
        <li key={i} data-testid="claim-log-line">{line}</li>
      ))}
    </ol>
  );
}

export const contribution = ClaimCells.fill({ order: 40, Component: ClaimLog });
import React from 'react';
import { createRoot } from 'react-dom/client';
import { RouterProvider, createRouter } from '@tanstack/react-router';
